class ThreadResumeParams(BaseModel):
    """
    There are three ways to resume a thread: 1. By thread_id: load the thread from disk by thread_id and resume it. 2. By history: instantiate the thread from memory and resume it. 3. By path: load the thread from disk by path and resume it.

    The precedence is: history > path > thread_id. If using history or path, the thread_id param will be ignored.

    Prefer using thread_id whenever possible.
    """

    approvalPolicy: AskForApproval1 | AskForApproval2 | None = None
    approvalsReviewer: ApprovalsReviewer | None = Field(
        default=None,
        description="Override where approval requests are routed for review on this thread and subsequent turns.",
    )
    baseInstructions: str | None = None
    config: dict[str, Any] | None = None
    cwd: str | None = None
    developerInstructions: str | None = None
    excludeTurns: bool | None = Field(
        default=None,
        description="When true, return only thread metadata and live-resume state without populating `thread.turns`. This is useful when the client plans to call `thread/turns/list` immediately after resuming.",
    )
    history: (
        list[
            ResponseItem1
            | ResponseItem2
            | ResponseItem3
            | ResponseItem4
            | ResponseItem5
            | ResponseItem6
            | ResponseItem7
            | ResponseItem8
            | ResponseItem9
            | ResponseItem10
            | ResponseItem11
            | ResponseItem12
            | ResponseItem13
            | ResponseItem14
        ]
        | None
    ) = Field(
        default=None,
        description="[UNSTABLE] FOR CODEX CLOUD - DO NOT USE. If specified, the thread will be resumed with the provided history instead of loaded from disk.",
    )
    model: str | None = Field(
        default=None,
        description="Configuration overrides for the resumed thread, if any.",
    )
    modelProvider: str | None = None
    path: str | None = Field(
        default=None,
        description="[UNSTABLE] Specify the rollout path to resume from. If specified, the thread_id param will be ignored.",
    )
    permissions: PermissionProfileSelectionParams | None = Field(
        default=None,
        description="Named profile selection for the resumed thread. Cannot be combined with `sandbox`. Use bounded `modifications` for supported thread adjustments instead of replacing the full permissions profile.",
    )
    persistExtendedHistory: bool | None = Field(
        default=False,
        description="Deprecated and ignored by app-server. Kept only so older clients can continue sending the field while rollout persistence always uses the limited history policy.",
    )
    personality: Personality | None = None
    sandbox: SandboxMode | None = None
    serviceTier: str | None = None
    threadId: str


